// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);

        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        vm.deal(bob, 2 ether);
        vm.prank(bob);
        c.addToBalance{value: 2 ether}();

        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), 1 ether);
        vm.prank(address(attacker));
        c.addToBalance{value: 1 ether}();

        vm.prank(address(attacker));
        try attacker.attack() {
        } catch {
        }

        uint256 bal = c.getBalance(address(attacker));
        assertTrue(bal == 1 ether);
    }
}

contract Attacker {
    Reentrance c;
    bool doReenter;

    constructor(Reentrance _c) {
        c = _c;
        doReenter = true;
    }

    function attack() external {
        c.withdrawBalance();
    }

    receive() external payable {
        if (doReenter) {
            doReenter = false;
            c.addToBalance{value: 1 ether}();
        }
    }
}
